mapper.select:
select a.*, concat(c.name, ' · ', s.name, ' · ', t.name, ' · ', sem.name) as courseLabel, concat('第', p1.period_no, '节 ', p1.start_time) as startPeriodLabel, concat('第', p2.period_no, '节 ', p2.end_time) as endPeriodLabel from course_arrangement a left join course co on a.course_id = co.id left join class c on co.class_id = c.id left join subject s on co.subject_id = s.id left join teacher t on co.teacher_id = t.id left join semester sem on co.semester_id = sem.id left join period p1 on a.start_period_id = p1.id left join period p2 on a.end_period_id = p2.id where 1=1
and co.class_id = #{dto.classId}
and co.teacher_id = #{dto.teacherId}
order by a.day_of_week, p1.period_no, a.id

SELECT a.id, c.name AS className, su.name AS subjectName, t.name AS teacherName, a.day_of_week AS dayOfWeek, a.classroom, p1.period_no AS startPeriod, p1.start_time AS startTime, p2.period_no AS endPeriod, p2.end_time AS endTime FROM course_arrangement a JOIN course co ON a.course_id = co.id JOIN class c ON co.class_id = c.id JOIN subject su ON co.subject_id = su.id JOIN teacher t ON co.teacher_id = t.id JOIN period p1 ON a.start_period_id = p1.id JOIN period p2 ON a.end_period_id = p2.id
AND c.id = #{dto.classId} AND t.id = #{dto.teacherId} AND a.day_of_week = #{dto.dayOfWeek}
ORDER BY a.day_of_week, p1.period_no
